      topic: brief.topic || '',
      story_reference: brief.story_reference || '',
      copywriter_dna: brief.copywriter_dna || 'Alex Hormozi',
      platform: brief.platform || 'LinkedIn',
      character_limit: brief.character_limit || 3000,
      revision_count: 0,
      max_revisions: 3,
      critic_feedback: '',
      pipeline_id: `batch-${new Date().toISOString().slice(0,10)}-${Math.random().toString(36).substr(2, 6)}`
    }
  });
}

return results;

