// Extract the Creator's content from the Claude API response
const response = $input.first().json;
const creatorContent = response.content?.[0]?.text || '';

// Pass through the brief metadata alongside the generated content
const brief = $('Prepare Brief & Init Loop').first().json;
// On revision cycles, pull from the loop merge node instead
const loopData = $('Merge: Revision Loop').first?.()?.json;
const sourceData = loopData || brief;

return [{
  json: {
    creator_output: creatorContent,
    content_type: sourceData.content_type,
    topic: sourceData.topic,
    story_reference: sourceData.story_reference,
    copywriter_dna: sourceData.copywriter_dna,
    platform: sourceData.platform,
    character_limit: sourceData.character_limit,
    revision_count: sourceData.revision_count || 0,
    max_revisions: sourceData.max_revisions || 3,
    pipeline_id: sourceData.pipeline_id
  }
}];

// Parse the Critic's response and extract score + feedback
const response = $input.first().json;
const criticRaw = response.content?.[0]?.text || '{}';

let criticData;
try {
  // Try to parse as JSON directly
  criticData = JSON.parse(criticRaw);
} catch (e) {
  // If JSON parsing fails, try to extract JSON from the response
  const jsonMatch = criticRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      criticData = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      criticData = { score: 0, pass: false, feedback: [{ issue: 'Failed to parse Critic response', fix: 'Check API response format' }], revision_instructions: 'Critic response could not be parsed. Manual review required.' };
    }
  } else {
    criticData = { score: 0, pass: false, feedback: [{ issue: 'No JSON found in Critic response', fix: 'Check Critic prompt' }], revision_instructions: 'No valid response from Critic.' };
  }
}

const prevData = $('Extract Creator Output').first().json;

return [{
  json: {
    ...prevData,
    critic_score: criticData.score || 0,
    critic_pass: criticData.pass || false,
    critic_scores_by_criterion: criticData.scores_by_criterion || {},
    critic_strengths: criticData.strengths || [],
    critic_feedback: JSON.stringify(criticData.feedback || [], null, 2),
    critic_revision_instructions: criticData.revision_instructions || '',
    critic_raw: criticRaw
  }
}];

// Increment revision count and prepare data for the Creator loop
const data = $input.first().json;

return [{
  json: {
    content_type: data.content_type,
    topic: data.topic,
    story_reference: data.story_reference,
    copywriter_dna: data.copywriter_dna,
    platform: data.platform,
    character_limit: data.character_limit,
    revision_count: (data.revision_count || 0) + 1,
    max_revisions: data.max_revisions || 3,
    pipeline_id: data.pipeline_id,
    critic_feedback: `CRITIC SCORE: ${data.critic_score}/100\n\nSCORES BY CRITERION:\n${JSON.stringify(data.critic_scores_by_criterion, null, 2)}\n\nFEEDBACK ITEMS:\n${data.critic_feedback}\n\nREVISION INSTRUCTIONS:\n${data.critic_revision_instructions}`
  }
}];

