// Parse the Approver's response and prepare final output
const response = $input.first().json;
const approverRaw = response.content?.[0]?.text || '{}';

let approverData;
try {
  approverData = JSON.parse(approverRaw);
} catch (e) {
  const jsonMatch = approverRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      approverData = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      approverData = { approver_score: 0, decision: 'flagged_for_human_review', notes: 'Failed to parse Approver response' };
    }
  } else {
    approverData = { approver_score: 0, decision: 'flagged_for_human_review', notes: 'No valid response from Approver' };
  }
}

const prevData = $('Quality Gate (Score >= 75?)').first().json;

return [{
  json: {
    pipeline_id: prevData.pipeline_id,
    content_type: prevData.content_type,
    topic: prevData.topic,
    platform: prevData.platform,
    copywriter_dna: prevData.copywriter_dna,
    revision_cycles: prevData.revision_count,
    critic_score: prevData.critic_score,
    approver_score: approverData.approver_score || 0,
    decision: approverData.decision || 'flagged_for_human_review',
    checks_passed: approverData.checks_passed || '0/8',
    pride_test: approverData.pride_test || 'unknown',
    approver_notes: approverData.notes || '',
    checks_detail: approverData.checks_detail || [],
    final_content: approverData.final_content || prevData.creator_output,
    approved_at: new Date().toISOString()
  }
}];

